"""Read-only candidate acceptance hash preview. No authorization/write/decision.
Exact disabled template is embedded; only its read/need/pure builder are called.
Full managed proof and acceptance body are never printed or saved.
"""
import argparse,base64,hashlib,json,os,re,subprocess,types
from pathlib import Path
TEMPLATE_SHA='3632ac149730434f2cbb0a79f1ebaad6549f94495759f3dc1bf2eb5b7c73e578'
TEMPLATE_B64=''
ROOT_TESTS={'ui':137,'backendStageAndResponse':12,'attentionCompatibility':12,'hostRouteIntegration':16,'independentRegression':10,'installer':146}
LOCK='/opt/synapse/.palitra-app-release.lock'
sha=lambda raw:hashlib.sha256(raw).hexdigest()
digest=lambda value:type(value) is str and re.fullmatch('[a-f0-9]{64}',value) is not None
def need(ok,code):
    if not ok:raise ValueError(code)
def load_template():
    raw=base64.b64decode(TEMPLATE_B64,validate=True)
    need(sha(raw)==TEMPLATE_SHA,'EXACT_DISABLED_TEMPLATE_REQUIRED')
    m=types.ModuleType('exact_disabled_approval_template');m.__file__='<embedded-disabled-template>'
    exec(compile(raw,m.__file__,'exec'),m.__dict__)
    need(m.TRANSPORT_READY is False and m.EXPECTED_PID is None and m.PREFLIGHT_PIN is None
         and m.ROOT_RUNTIME_ACCEPTANCE_SHA is None and m.ROOT_LOCAL_TESTS is None,'DISABLED_UNAPPROVED_TEMPLATE_REQUIRED')
    return m
def readonly_lslocks():
    return subprocess.check_output(['lslocks','--noheadings','--output','PID,PATH'],timeout=10)
def lease(pid,run):
    raw=run();need(type(raw) is bytes and len(raw)<=1048576,'BOUNDED_READONLY_LEASE_REQUIRED')
    rows=[row.strip().split(maxsplit=1) for row in raw.decode('utf-8').splitlines()]
    need([row for row in rows if len(row)==2 and row[1]==LOCK]==[[str(pid),LOCK]],'OWN_EXACT_FRESH_LEASE_REQUIRED')
def validate_preflight(m,pre):
    need(type(pre) is dict and pre.get('status')=='CURRENT_NEBO_NOTIFY_READONLY_NOT_APPROVED'
         and pre.get('runtimeWrites')==pre.get('contentSchemaObjectsCreated')==0
         and pre.get('productReviewSha256')==m.BINDINGS['productReviewSha256']
         and pre.get('rootProductAcceptanceSha256')==m.BINDINGS['rootProductAcceptanceSha256']
         and pre.get('neboBasisSha256')==m.NEBO_BASIS_PIN
         and pre.get('responseModuleSha256')==m.BINDINGS['responseModuleSha256']
         and pre.get('attentionDependencies')==m.BINDINGS['attentionDependencies']
         and (pre.get('sourceFiles'),pre.get('staticFiles'),pre.get('chainFiles'),pre.get('candidateSourceFiles'),pre.get('candidateStaticFiles'))==(235,41,41,239,43),'EXACT_PASSED_PREFLIGHT_REQUIRED')
    need(digest(pre.get('parentPostSchemaSha256')) and pre.get('trafficDatabaseBefore',{}).get('status') in ('ABSENT','EXISTING'),'REVIEWED_SCHEMA_AND_THIRD_STORE_REQUIRED')
def preview(pid,pin,m,run=readonly_lslocks):
    need(type(pid) is int and pid>1 and digest(pin),'ACTUAL_PID_AND_EXPLICIT_PREFLIGHT_SHA_REQUIRED')
    need(m.TRANSPORT_READY is False and m.EXPECTED_PID is None and m.ROOT_RUNTIME_ACCEPTANCE_SHA is None,'PREVIEW_CANNOT_AUTHORIZE_RUNTIME')
    lease(pid,run)
    pre_path=Path('/tmp/darya-r2-readonly-'+str(pid)+'.json')
    managed_path=m.ROOT/'multi-company-app-20261019-r7c-managed-proof.json'
    pre_raw=m.read(pre_path,pin);pre=json.loads(pre_raw);validate_preflight(m,pre)
    managed_raw=m.read(managed_path,m.BINDINGS['managedProofSha256']);managed=json.loads(managed_raw)
    need(managed['current']['version']==259 and managed['historical']['version']==257 and managed['current']['mismatches']==[],'EXACT_MANAGED_SOURCE_REQUIRED')
    # Exactly two pure-construction constants are set. Approval remains disabled.
    m.PREFLIGHT_PIN=pin;m.ROOT_LOCAL_TESTS=dict(ROOT_TESTS)
    value=m.build_acceptance(pre,managed)
    canonical=(json.dumps(value,sort_keys=True,separators=(',',':'))+'\n').encode()
    need(m.read(pre_path,pin)==pre_raw and m.read(managed_path,m.BINDINGS['managedProofSha256'])==managed_raw,'READONLY_INPUTS_CHANGED')
    lease(pid,run)
    need(m.TRANSPORT_READY is False and m.EXPECTED_PID is None and m.ROOT_RUNTIME_ACCEPTANCE_SHA is None,'PREVIEW_CANNOT_AUTHORIZE_RUNTIME')
    # Never include managed, acceptance body, customer metadata, paths or SQL data.
    return {'status':'UNAPPROVED_ROOT_ACCEPTANCE_HASH_PREVIEW','acceptanceSha256':sha(canonical),
      'readonlyPreflightSha256':pin,'helperSha256':m.PINS['release-native.py'],
      'rootProductAcceptanceSha256':m.BINDINGS['rootProductAcceptanceSha256'],
      'neboBasisSha256':m.NEBO_BASIS_PIN,'managedProofSha256':m.BINDINGS['managedProofSha256'],
      'sourceCounts':{'before':235,'after':239},'staticCounts':{'before':41,'after':43},'chainCounts':{'before':41,'after':42},
      'rootLocalTests':dict(ROOT_TESTS),'authorizationGranted':False,'acceptanceWrites':0,'decisionWrites':0,'runtimeWrites':0,'databaseWrites':0}
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--lease-pid',type=int,required=True);parser.add_argument('--preflight-sha',required=True);args=parser.parse_args()
    try:
        need(os.name=='posix' and os.geteuid()==0,'ROOT_READONLY_PREVIEW_REQUIRED')
        result=preview(args.lease_pid,args.preflight_sha,load_template())
        print(json.dumps(result,sort_keys=True,separators=(',',':')));return 0
    except Exception as error:
        code=str(error) if type(error) is ValueError and re.fullmatch('[A-Z][A-Z0-9_]{0,100}',str(error)) else 'READONLY_PREVIEW_REFUSED'
        print(json.dumps({'status':'READONLY_PREVIEW_REFUSED_NOT_AUTHORIZED','code':code,'acceptanceWrites':0,'decisionWrites':0,'runtimeWrites':0,'databaseWrites':0},separators=(',',':')));return 2
if __name__=='__main__':raise SystemExit(main())
